def _type_errors_as_value_errors(
    validator: Callable[[Any], Any], value: Any
) -> Any:
    """Run a validator, reporting TypeError as ValueError.

    Pydantic 2 no longer converts TypeError raised inside validators into a
    ValidationError, so it is converted here to keep failing inputs reported as
    validation errors.
    """
    try:
